import Foundation
import UniformTypeIdentifiers

/// What the preview's URL scheme serves for a URL.
public enum PreviewResource: Equatable {
    /// Content generated by the app.
    case content(Data, mimeType: String)
    case file(URL)
}

/// Maps preview URLs to what they serve: the shell page and its assets (app origin), plugin folders
/// (plugin origins) and the open document's folder (document origin). Anything else is not served.
public struct PreviewResources {
    private let page: PreviewPage
    private let previewFolder: URL
    private let pluginFolders: [String: URL]
    public var documentFolder: URL?

    /// - Parameter previewFolder: folder holding `preview.js` and `preview.css`.
    public init(page: PreviewPage, previewFolder: URL, plugins: [LoadedPlugin], documentFolder: URL? = nil) {
        self.page = page
        self.previewFolder = previewFolder
        pluginFolders = Dictionary(plugins.map { ($0.plugin.id, $0.folder) }, uniquingKeysWith: { first, _ in first })
        self.documentFolder = documentFolder
    }

    public static let shellURL = URL(string: PreviewOrigins.appOrigin + PreviewPageBuilder.pageFileName)!

    public func resolve(_ url: URL) -> PreviewResource? {
        guard url.scheme?.lowercased() == PreviewOrigins.scheme, let host = url.host?.lowercased() else { return nil }
        if host == PreviewOrigins.appHost {
            if url.path == "/" + PreviewPageBuilder.pageFileName {
                return .content(Data(page.html.utf8), mimeType: "text/html")
            }
            return file(in: previewFolder, at: url)
        }
        if host == PreviewOrigins.documentHost {
            return documentFolder.flatMap { file(in: $0, at: url) }
        }
        return PreviewOrigins.pluginID(ofHost: host).flatMap { pluginFolders[$0] }.flatMap { file(in: $0, at: url) }
    }

    /// The file a stylesheet URL of the preview is served from (shell and plugin stylesheets only).
    public func stylesheetFile(_ urlString: String) -> URL? {
        guard let url = URL(string: urlString), url.host?.lowercased() != PreviewOrigins.documentHost,
              case .file(let file) = resolve(url) else { return nil }
        return file
    }

    /// The file under `folder` the URL path designates; nil for a path escaping the folder.
    private func file(in folder: URL, at url: URL) -> PreviewResource? {
        let relative = String(url.path.drop { $0 == "/" })
        guard !relative.isEmpty else { return nil }
        let root = folder.standardizedFileURL.path
        let file = folder.appendingPathComponent(relative).standardizedFileURL
        guard file.path.hasPrefix(root.hasSuffix("/") ? root : root + "/") else { return nil }
        return .file(file)
    }

    /// Web types the system type registry does not know.
    private static let webMimeTypes = ["woff2": "font/woff2", "woff": "font/woff", "wasm": "application/wasm"]

    public static func mimeType(of file: URL) -> String {
        let fileExtension = file.pathExtension.lowercased()
        return webMimeTypes[fileExtension] ?? UTType(filenameExtension: fileExtension)?.preferredMIMEType ?? "application/octet-stream"
    }
}
